<?php
require dirname(__DIR__).'/app/bootstrap.php';
$ch=curl_init('https://open.er-api.com/v6/latest/EUR');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>25,CURLOPT_SSL_VERIFYPEER=>true]);$raw=curl_exec($ch);$status=curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);$d=json_decode((string)$raw,true);if($status!==200||($d['result']??'')!=='success'||time()-(int)($d['time_last_update_unix']??0)>172800)throw new RuntimeException('Fresh EUR rates unavailable; existing rates retained.');$pdo=db();$pdo->beginTransaction();try{$q=$pdo->prepare('UPDATE gateway_fx_rates SET units_per_eur=?,active=1,updated_at=UTC_TIMESTAMP() WHERE currency=?');foreach(['KES','USD','CDF','UGX','XOF','XAF','RWF','ZMW','SLE'] as $c){$v=$d['rates'][$c]??0;if(!is_numeric($v)||$v<=0)throw new RuntimeException('Missing supported currency rate');$q->execute([$v,$c]);}$pdo->commit();echo "EUR exchange rates refreshed.\n";}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
